import sys

n = int(sys.stdin.read().split()[0])
M = 10 ** 9 + 7
N = 2 * n
cur = {0: 1}
for p in range(N):
    nxt = {}
    c = p // 2
    cells = [2 * c, 2 * c + 1, 2 * c + 2, 2 * c + 3]
    shapes = [(p, p + 2)]
    if p % 2 == 0:
        shapes.append((p, p + 1))
    for skip in range(4):
        tri = tuple(x for k, x in enumerate(cells) if k != skip)
        if p in tri and min(tri) == p:
            shapes.append(tri)
    for m, cnt in cur.items():
        if m & 1:
            nm = m >> 1
            nxt[nm] = (nxt.get(nm, 0) + cnt) % M
            continue
        for sh in shapes:
            if max(sh) >= N:
                continue
            bits = 0
            ok = True
            for x in sh:
                b = 1 << (x - p)
                if m & b:
                    ok = False
                    break
                bits |= b
            if ok:
                nm = (m | bits) >> 1
                nxt[nm] = (nxt.get(nm, 0) + cnt) % M
    cur = nxt
print(cur.get(0, 0) % M)

